<?php
/**
 * ASTRO SIVAM source-based astrologer - local knowledge-base mode.
 *
 * Every reply is assembled from ASTRO SIVAM's own sources only:
 *
 *   1. the customer's own report readings (AstroEngine's per-area summary,
 *      rebuilt from the saved order inputs - the same text as the PDF),
 *   2. the curated classical rules in knowledge/ai-astrologer/rules/
 *      life-areas.json, evaluated against the customer's chart,
 *   3. the remedies registry (knowledge/ai-astrologer/rules/remedies.json),
 *   4. the fixed refusal routes and guardrails.
 *
 * Nothing is generated by a language model, so nothing unreviewed can reach a
 * customer, and the chat works on any host with no paid service. The same
 * output guard (AstroAiProvider::checkReply) still runs on every reply.
 *
 * Returns the same shape as AstroAiProvider::answer() so the endpoint and the
 * browser do not need to know which mode produced the answer.
 */

require_once __DIR__ . '/ai_astrologer_provider.php';

class AstroAiOffline
{
