        'health' => 'health',
        'wealth' => 'wealth',
        'education' => 'education',
        'career' => 'career',
        'marriage' => 'marriage',
        'property' => 'family',
        'travel-foreign' => 'foreignTravel',
        'current-guidance' => 'currentPeriodGuidance',
    ];

