        'marriage' => ['marriage', 'married', 'marry', 'wedding', 'wife', 'husband', 'spouse', 'partner', 'love', 'relationship', 'divorce', 'child', 'children', 'baby',
            'திருமணம்', 'கல்யாணம்', 'மனைவி', 'கணவர்', 'காதல்', 'குழந்தை', 'विवाह', 'शादी', 'पत्नी', 'पति', 'प्रेम', 'संतान', 'बच्चे'],
        'wealth' => ['money', 'wealth', 'finance', 'income', 'debt', 'loan', 'savings', 'rich', 'financial',
            'பணம்', 'செல்வம்', 'வருமானம்', 'கடன்', 'சேமிப்பு', 'धन', 'पैसा', 'आय', 'कर्ज', 'बचत'],
        'education' => ['study', 'studies', 'exam', 'education', 'college', 'school', 'degree', 'university',
            'படிப்பு', 'கல்வி', 'தேர்வு', 'பரீட்சை', 'पढ़ाई', 'शिक्षा', 'परीक्षा'],
        'property' => ['house', 'home', 'land', 'property', 'flat', 'apartment', 'vehicle', 'car',
            'வீடு', 'நிலம்', 'சொத்து', 'வாகனம்', 'घर', 'जमीन', 'संपत्ति', 'मकान', 'वाहन'],
        'travel-foreign' => ['abroad', 'foreign', 'travel', 'visa', 'overseas', 'settle', 'migrate', 'australia', 'canada', 'usa', 'uk', 'new zealand',
            'வெளிநாடு', 'பயணம்', 'விசா', 'विदेश', 'यात्रा', 'वीज़ा', 'वीजा'],
        'health' => ['health', 'sick', 'illness', 'pain', 'tired', 'sleep', 'stress', 'anxiety',
            'உடல்நலம்', 'நோய்', 'தூக்கம்', 'மன அழுத்தம்', 'स्वास्थ्य', 'बीमार', 'नींद', 'तनाव'],
        'current-guidance' => ['dasha', 'dasa', 'bhukti', 'period', 'this year', 'next year', 'future', 'sade sati', 'ezharai', 'nakshatra', 'star', 'panchangam', 'horoscope', 'chart', 'my life',
            'தசை', 'திசை', 'புக்தி', 'ஏழரை', 'நட்சத்திரம்', 'ஜாதகம்', 'எதிர்காலம்', 'இந்த வருடம்', 'பஞ்சாங்கம்',
            'दशा', 'भुक्ति', 'साढ़े साती', 'नक्षत्र', 'कुंडली', 'भविष्य', 'इस साल'],
    ];

    /** Words that make a question about the running period itself. */
    const PERIOD_WORDS = ['dasha', 'dasa', 'bhukti', 'mahadasha', 'antardasha', 'sade sati', 'nakshatra', 'birth star', 'panchangam', 'panchang',
        'தசை', 'திசை', 'புக்தி', 'ஏழரை', 'நட்சத்திரம்', 'பஞ்சாங்கம்', 'दशा', 'भुक्ति', 'साढ़े साती', 'नक्षत्र', 'पंचांग'];

    const REMEDY_WORDS = ['remedy', 'remedies', 'pariharam', 'parikaram', 'parihara', 'mantra', 'temple', 'pooja', 'puja', 'prayer', 'fasting', 'charity',
        'பரிகாரம்', 'மந்திரம்', 'கோயில்', 'கோவில்', 'பூஜை', 'விரதம்', 'தானம்', 'उपाय', 'मंत्र', 'मंदिर', 'पूजा', 'व्रत', 'दान'];

    const TIMING_WORDS = ['when', 'which year', 'how long', 'what time', 'எப்போது', 'எப்பொழுது', 'எந்த வருடம்', 'எவ்வளவு காலம்', 'कब', 'किस साल', 'कितने समय'];

    const GREETING_WORDS = ['hi', 'hello', 'hey', 'vanakkam', 'namaste', 'namaskar', 'good morning', 'good evening', 'thanks', 'thank you',
        'வணக்கம்', 'நன்றி', 'नमस्ते', 'नमस्कार', 'धन्यवाद'];

    /** Rule-vocabulary graha => names a customer might type. */
    const PLANET_NAMES = [
        'Surya' => ['surya', 'sun', 'suriyan', 'சூரியன்', 'सूर्य'],
        'Chandra' => ['chandra', 'moon', 'chandran', 'சந்திரன்', 'चंद्र', 'चन्द्र'],
        'Sevvai' => ['sevvai', 'chevvai', 'mars', 'kuja', 'mangal', 'செவ்வாய்', 'मंगल'],
        'Budha' => ['budha', 'budhan', 'mercury', 'புதன்', 'बुध'],
        'Guru' => ['guru', 'jupiter', 'brihaspati', 'குரு', 'गुरु', 'बृहस्पति'],
        'Sukra' => ['sukra', 'sukran', 'shukra', 'venus', 'சுக்கிரன்', 'சுக்ரன்', 'शुक्र'],
        'Sani' => ['sani', 'shani', 'saturn', 'சனி', 'शनि'],
