    // ------------------------------------------------------------------
    // Entry point
    // ------------------------------------------------------------------

    /**
     * @param array|null $chart   AstroAiProvider chart facts (may carry 'summary' and 'labels').
     * @param array      $context customerName, chartHeader, dashaEndDate, ...
     * @return array{content:string, bubbles:array, sourceLine:string, areaId:?string, handoff:bool, mode:string}
     */
    public static function answer(string $question, string $language, ?array $chart, array $context = []): array
    {
        $lang = in_array($language, ['en', 'ta', 'hi'], true) ? $language : 'en';
        $q = mb_strtolower(trim($question), 'UTF-8');
        $name = trim((string) ($context['customerName'] ?? ''));
        if ($name === '' || $name === 'there') {
            $name = '';
        }

        // 1. Fixed refusal routes always win (legal, money, medicine, lifespan, curse, price).
        $retrieved = AstroAiProvider::retrieve($question, $lang, $chart);
        if (!empty($retrieved['refusal']) && ($retrieved['refusal']['route'] ?? '') === 'no-sales'
            && ($extra = self::matchExtraArea($q)) !== null) {
            // "how much money will I earn" is a wealth question, not a price question.
            $retrieved = self::retrieveArea($extra, $question, $lang, $chart);
        }
        if (!empty($retrieved['refusal'])) {
            $text = self::refusalText((string) $retrieved['refusal']['route'], (string) $retrieved['refusal']['text'], $lang);
            return self::finish([$text], '', null, true, $lang);
        }

        // 2. A plain greeting gets a greeting and the list of topics.
        if (self::isGreeting($q)) {
            return self::finish([self::greeting($name, $lang, $chart !== null), self::topicsLine($lang)], '', null, false, $lang);
        }

        // Area choice on WHOLE words (the shared retrieve() matches substrings,
        // so "current" would hit the property phrase "rent"). Re-scope the
        // rules when the whole-word winner differs.
        $areaId = self::matchExtraArea($q);
        if ($areaId !== null && $areaId !== ($retrieved['areaId'] ?? null)) {
            $retrieved = self::retrieveArea($areaId, $question, $lang, $chart);
        }

        $planet = self::mentionedPlanet($q);
        $wantsRemedy = self::containsAny($q, self::REMEDY_WORDS);

        // 3. A remedy question with no life-area: remedies registry only.
        if ($areaId === null && ($wantsRemedy || $planet !== null)) {
            $bubbles = [self::remedyText($planet ?? self::dashaPlanet($chart), $lang)];
            if ($chart === null) {
                $bubbles[] = self::personalHint($lang);
            }
            return self::finish($bubbles, self::remedySourceLine($planet ?? self::dashaPlanet($chart)), null, false, $lang);
        }

        // 4. Nothing in the knowledge base matches: say so honestly and offer the astrologer.
        if ($areaId === null) {
            return self::finish([self::noMatchText($lang), self::topicsLine($lang)], '', null, true, $lang);
        }

        // 5. A life-area answer.
        $bubbles = self::areaBubbles($areaId, $retrieved, $question, $lang, $chart, $context, $name);
        if ($wantsRemedy || $planet !== null) {
            $bubbles[] = self::remedyText($planet ?? self::dashaPlanet($chart), $lang);
        }
        if ($areaId === 'health') {
            $bubbles[] = self::doctorLine($lang);
        }

        $sourceLine = AstroAiProvider::tamilOnlySourceLine((string) ($retrieved['sourceLine'] ?? ''));
        return self::finish($bubbles, $sourceLine, $areaId, $areaId === 'health', $lang);
    }

    // ------------------------------------------------------------------
    // Life-area answers
    // ------------------------------------------------------------------

    private static function areaBubbles(string $areaId, array $retrieved, string $question, string $lang, ?array $chart, array $context, string $name): array
    {
        $title = (string) ($retrieved['cardTitle'] ?? $areaId);
        $bubbles = [];

        if ($areaId === 'current-guidance') {
            return self::currentGuidanceBubbles($retrieved, $question, $lang, $chart, $name);
        }

        if ($chart === null) {
            $bubbles[] = self::t($lang, [
                'en' => 'Here is how Tamil astrology reads ' . $title . ':',
                'ta' => $title . ' பற்றி தமிழ் ஜோதிடம் சொல்வது:',
                'hi' => $title . ' के बारे में तमिल ज्योतिष क्या कहता है:',
            ]) . "\n" . self::generalAreaText($areaId, $lang);
            $bubbles[] = self::personalHint($lang);
            return $bubbles;
        }

        // The customer's own report reading for this card.
        $summary = self::summaryText($chart, $areaId, $lang);
        $intro = self::t($lang, [
            'en' => ($name !== '' ? $name . ', h' : 'H') . 'ere is what your horoscope shows for ' . $title . ':',
            'ta' => ($name !== '' ? $name . ', ' : '') . 'உங்கள் ஜாதகப்படி ' . $title . ':',
            'hi' => ($name !== '' ? $name . ', ' : '') . 'आपकी कुंडली के अनुसार ' . $title . ':',
        ]);
        $bubbles[] = $intro . "\n" . ($summary !== '' ? $summary : self::generalAreaText($areaId, $lang));

        // Classical rules that actually fired on this chart.
        $ruleLines = [];
        $tips = [];
        foreach (($retrieved['rules'] ?? []) as $rule) {
            if (count($ruleLines) >= 2) {
                break;
            }
            $meaning = trim((string) ($rule['meaning'] ?? ''));
            if ($meaning === '') {
                continue;
            }
            $ruleLines[] = '• ' . $meaning;
            foreach (($rule['practical'] ?? []) as $p) {
                $tips[] = (string) $p;
            }
        }
        if ($ruleLines) {
            $bubbles[] = self::t($lang, [
                'en' => 'What the classical Tamil texts add for your chart:',
                'ta' => 'உங்கள் ஜாதகத்திற்கு மரபு தமிழ் நூல்கள் சொல்வது:',
                'hi' => 'आपकी कुंडली पर शास्त्रीय तमिल ग्रंथ क्या जोड़ते हैं:',
            ]) . "\n" . implode("\n", $ruleLines);
        }
        // Practical steps are written in English in the rule base.
        if ($tips && $lang === 'en') {
            $bubbles[] = 'Practical steps: ' . implode('; ', array_slice(array_values(array_unique($tips)), 0, 3)) . '.';
        }

        if (self::containsAny(mb_strtolower($question, 'UTF-8'), self::TIMING_WORDS)) {
            $period = self::periodLine($chart, $lang);
            if ($period !== '') {
                $bubbles[] = $period . ' ' . self::t($lang, [
                    'en' => 'Astrology shows favourable and slower periods, not fixed dates - your own effort decides the outcome.',
                    'ta' => 'ஜோதிடம் சாதகமான மற்றும் மெதுவான காலங்களை காட்டுகிறது, உறுதியான தேதிகளை அல்ல - உங்கள் முயற்சியே முடிவை தீர்மானிக்கும்.',
                    'hi' => 'ज्योतिष अनुकूल और धीमे समय दिखाता है, तय तारीखें नहीं - परिणाम आपके प्रयास पर निर्भर है।',
                ]);
            }
        }

        return $bubbles;
    }

    private static function currentGuidanceBubbles(array $retrieved, string $question, string $lang, ?array $chart, string $name): array
    {
        $bubbles = [];
        if ($chart === null) {
            $bubbles[] = self::generalAreaText('current-guidance', $lang);
            $bubbles[] = self::personalHint($lang);
        } else {
            $period = self::periodLine($chart, $lang);
            $star = self::starLine($chart, $lang);
            if ($name !== '' && $lang === 'en' && $period !== '') {
                $period = lcfirst($period);
            }
            $first = trim(($name !== '' ? $name . ', ' : '') . $period . ($star !== '' ? ' ' . $star : ''));
            $bubbles[] = $first !== '' ? $first : self::generalAreaText('current-guidance', $lang);
            $summary = self::summaryText($chart, 'current-guidance', $lang);
            if ($summary !== '') {
                $bubbles[] = $summary;
            }
            $bubbles[] = self::t($lang, [
                'en' => 'The Mahadasha is the broad chapter of life you are in; the Bhukti is the shorter section inside it, and it shapes the present most closely.',
                'ta' => 'மகாதசை என்பது நீங்கள் இருக்கும் வாழ்க்கையின் பெரிய அத்தியாயம்; புக்தி அதற்குள் உள்ள சிறு பகுதி - தற்போதைய நிலையை அதுவே நெருக்கமாக காட்டுகிறது.',
                'hi' => 'महादशा जीवन का बड़ा अध्याय है; भुक्ति उसके भीतर का छोटा हिस्सा है, और वर्तमान को वही सबसे करीब से दिखाती है।',
            ]);
        }

        // The panchangam explanation, when the customer asks about it. The rule
        // text opens with a one-sentence instruction; the rest is customer-facing.
        foreach (($retrieved['rules'] ?? []) as $rule) {
            if (($rule['id'] ?? '') === 'current-panchangam-difference') {
                $text = (string) ($rule['meaning'] ?? '');
                $cut = $lang === 'hi' ? mb_strpos($text, '। ', 0, 'UTF-8') : mb_strpos($text, '. ', 0, 'UTF-8');
                if ($cut !== false) {
                    $bubbles[] = trim(mb_substr($text, $cut + 2, null, 'UTF-8'));
                }
            }
        }
        return $bubbles;
    }

    /** Re-runs retrieval scoped to one area (used when only an extra phrase matched). */
    private static function retrieveArea(string $areaId, string $question, string $lang, ?array $chart): array
    {
        $kb = json_decode((string) file_get_contents(self::kbFile('/knowledge/ai-astrologer/rules/life-areas.json')), true) ?: [];
        foreach (($kb['areas'] ?? []) as $area) {
            if (($area['id'] ?? '') !== $areaId) {
                continue;
            }
            $rules = [];
            $sources = [];
            foreach (($area['rules'] ?? []) as $rule) {
                if (!AstroAiProvider::evaluateCondition($rule['condition'] ?? [], $chart, $question)) {
                    continue;
                }
                $labels = [];
                foreach (($rule['source'] ?? []) as $s) {
                    if (($s['level'] ?? 'book') !== 'suppressed') {
                        $labels[] = AstroAiProvider::formatCitation($s, $lang);
                    }
                }
                $rules[] = [
                    'id' => $rule['id'],
                    'meaning' => $rule['meaning'][$lang] ?? ($rule['meaning']['en'] ?? ''),
                    'easing' => $rule['easing'] ?? '',
                    'practical' => $rule['practical'] ?? [],
                    'sources' => $labels,
                ];
                $sources = array_merge($sources, $labels);
            }
            $unique = array_values(array_unique($sources));
            return [
                'areaId' => $areaId,
                'cardTitle' => $area['cardTitle'][$lang] ?? ($area['cardTitle']['en'] ?? $areaId),
                'rules' => $rules,
                'sourceLine' => $unique ? 'Source: ' . implode(' · ', array_slice($unique, 0, 3)) : '',
                'refusal' => null,
            ];
        }
        return ['areaId' => $areaId, 'cardTitle' => $areaId, 'rules' => [], 'sourceLine' => '', 'refusal' => null];
    }

    private static function kbFile(string $rel): string
    {
        foreach ([dirname(__DIR__, 2) . $rel, dirname(__DIR__) . $rel] as $candidate) {
            if (is_file($candidate)) {
                return $candidate;
            }
        }
        return dirname(__DIR__, 2) . $rel;
    }

    // ------------------------------------------------------------------
    // Chart-derived lines
    // ------------------------------------------------------------------

    private static function summaryText(array $chart, string $areaId, string $lang): string
    {
        $prefix = self::SUMMARY_KEYS[$areaId] ?? null;
        if ($prefix === null) {
            return '';
        }
        $suffix = $lang === 'ta' ? 'Ta' : ($lang === 'hi' ? 'Hi' : 'En');
        $text = trim((string) ($chart['summary'][$prefix . $suffix] ?? ''));
        if ($text === '' && $suffix !== 'En') {
            $text = trim((string) ($chart['summary'][$prefix . 'En'] ?? ''));
        }
        return $text;
    }

    private static function periodLine(?array $chart, string $lang): string
    {
        if ($chart === null) {
            return '';
        }
        $labels = $chart['labels'] ?? [];
        $maha = (string) ($labels['dasha'][$lang] ?? ($chart['currentDasha'] ?? ''));
        $bhukti = (string) ($labels['bhukti'][$lang] ?? ($chart['currentAntardasha'] ?? ''));
        $end = (string) ($chart['dashaEndDate'] ?? '');
        if ($maha === '') {
            return '';
        }
        if ($lang === 'ta') {
            return 'நீங்கள் தற்போது ' . $maha . ' மகாதசை' . ($bhukti !== '' ? ', ' . $bhukti . ' புக்தியில்' : 'யில்') . ' இருக்கிறீர்கள்'
                . ($end !== '' ? '; இந்த புக்தி ' . $end . ' வரை நீடிக்கும்.' : '.');
        }
        if ($lang === 'hi') {
            return 'आप अभी ' . $maha . ' महादशा' . ($bhukti !== '' ? ' और ' . $bhukti . ' भुक्ति' : '') . ' में हैं'
                . ($end !== '' ? '; यह भुक्ति ' . $end . ' तक चलेगी।' : '।');
        }
        return 'You are now in ' . $maha . ' Mahadasha' . ($bhukti !== '' ? ' with ' . $bhukti . ' Bhukti' : '')
            . ($end !== '' ? ', which runs until ' . $end . '.' : '.');
    }

    private static function starLine(array $chart, string $lang): string
    {
        $labels = $chart['labels'] ?? [];
        $star = (string) ($labels['nakshatra'][$lang] ?? ($chart['moonNakshatra'] ?? ''));
        $rasi = (string) ($labels['rasi'][$lang] ?? ($chart['moonSign'] ?? ''));
        $lagna = (string) ($labels['lagna'][$lang] ?? ($chart['lagna'] ?? ''));
        if ($star === '' && $rasi === '' && $lagna === '') {
            return '';
        }
        if ($lang === 'ta') {
            return 'உங்கள் லக்னம் ' . $lagna . ', ராசி ' . $rasi . ', நட்சத்திரம் ' . $star . '.';
        }
        if ($lang === 'hi') {
            return 'आपका लग्न ' . $lagna . ', राशि ' . $rasi . ' और नक्षत्र ' . $star . ' है।';
        }
        return 'Your Lagna is ' . $lagna . ', your Moon sign (Rasi) is ' . $rasi . ' and your birth star is ' . $star . '.';
    }

    /** Rule-vocabulary graha of the running Mahadasha, if a chart is attached. */
    private static function dashaPlanet(?array $chart): ?string
    {
        $p = (string) ($chart['currentDasha'] ?? '');
        return $p !== '' && isset(self::PLANET_NAMES[$p]) ? $p : null;
    }

    // ------------------------------------------------------------------
    // Remedies
    // ------------------------------------------------------------------

    private static function remedyText(?string $planet, string $lang): string
    {
        $reg = json_decode((string) file_get_contents(self::kbFile('/knowledge/ai-astrologer/rules/remedies.json')), true) ?: [];
        if ($planet !== null) {
            foreach (($reg['grahas'] ?? []) as $g) {
                if (($g['graha'] ?? '') !== $planet) {
                    continue;
                }
                $label = $lang === 'ta' ? (string) ($g['tamil'] ?? $planet) . ' (' . $planet . ')'
                    : ($lang === 'hi' ? (string) ($g['hindi'] ?? $planet) . ' (' . $planet . ')' : $planet);
                $l = self::t($lang, [
                    'en' => ['Simple remedies for ', 'Day: ', 'Prayer: ', 'Charity: ', 'Temple: '],
                    'ta' => [' - எளிய பரிகாரங்கள்', 'கிழமை: ', 'வழிபாடு: ', 'தானம்: ', 'கோயில்: '],
                    'hi' => [' - सरल उपाय', 'दिन: ', 'प्रार्थना: ', 'दान: ', 'मंदिर: '],
                ]);
                $head = $lang === 'en' ? $l[0] . $label . ':' : $label . $l[0] . ':';
                return $head
                    . "\n• " . $l[1] . ($g['weekday'] ?? '')
                    . "\n• " . $l[2] . ($g['mantra']['simple'] ?? '')
                    . "\n• " . $l[3] . ($g['charity'] ?? '')
                    . "\n• " . $l[4] . ($g['temple']['name'] ?? '')
                    . "\n" . self::t($lang, [
                        'en' => 'Do what you can with devotion - no costly ritual is needed.',
                        'ta' => 'உங்களால் முடிந்ததை பக்தியுடன் செய்யுங்கள் - செலவான சடங்குகள் தேவையில்லை.',
                        'hi' => 'जो संभव हो, श्रद्धा से करें - महंगे अनुष्ठान की आवश्यकता नहीं है।',
                    ]);
            }
        }
        $lines = [];
        foreach (($reg['universal'] ?? []) as $u) {
            $lines[] = '• ' . ($u['offer'] ?? '');
        }
        return self::t($lang, [
            'en' => 'Simple remedies our texts recommend for everyone:',
            'ta' => 'எல்லோருக்கும் எங்கள் நூல்கள் பரிந்துரைக்கும் எளிய பரிகாரங்கள்:',
            'hi' => 'हमारे ग्रंथ सबके लिए ये सरल उपाय बताते हैं:',
        ]) . "\n" . implode("\n", array_slice($lines, 0, 3));
    }

    private static function remedySourceLine(?string $planet): string
    {
        $reg = json_decode((string) file_get_contents(self::kbFile('/knowledge/ai-astrologer/rules/remedies.json')), true) ?: [];
        $ids = [];
        foreach (($reg['grahas'] ?? []) as $g) {
            if ($planet !== null && ($g['graha'] ?? '') === $planet) {
                foreach (($g['source'] ?? []) as $s) {
                    $ids[] = (string) ($s['id'] ?? '');
                }
            }
        }
        $ids = array_values(array_filter(array_unique($ids), [AstroAiProvider::class, 'isCitableId']));
        return $ids ? 'Source: ' . implode(' · ', array_slice($ids, 0, 3)) : '';
    }

